class HasOrganizationBillingPrivilege(permissions.BasePermission):
    def has_permission(self, request, view):
        return request.user.is_authenticated and request.user.has_billing_privileges

    def has_object_permission(self, request, view, obj):
        return obj.organization == request.user.organization

class OrganizationSubscriptionDetailView(generics.RetrieveUpdateAPIView):
    serializer_class = SubscriptionSerializer
    permission_classes = [HasOrganizationBillingPrivilege]

    def get_queryset(self):
        return OrganizationSubscription.objects.filter(organization=self.request.user.organization)
